import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.ServerSocket;
import java.net.Socket;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.UUID;

public class ServidorDemuxDeBorda {

    // A única porta que o balanceador público enxerga
    private static final int PORTA_UNICA = 8080;

    // Endereço do ALB interno
    private static final String URL_ALB_INTERNO =
            "http://alb_interno_aws/api/processar";

    // Cliente HTTP reutilizado para evitar criação desnecessária
    // de conexões e objetos a cada requisição.
    private static final HttpClient clienteHttp =
            HttpClient.newHttpClient();

    public static void main(String[] args) throws IOException {

        ServerSocket servidor =
                new ServerSocket(PORTA_UNICA);

        System.out.println(
                "Demux aguardando conexões na porta "
                + PORTA_UNICA
        );

        while (true) {

            Socket clienteConectado =
                    servidor.accept();

            // Exemplo didático:
            // cada conexão recebe uma thread.
            new Thread(() ->
                    processarConexao(clienteConectado)
            ).start();
        }
    }

    private static void processarConexao(
            Socket socket) {

        try (
            socket;
            InputStream entrada =
                    socket.getInputStream();
            OutputStream saida =
                    socket.getOutputStream()
        ) {

            // Lê o primeiro byte para descobrir
            // qual cliente está falando.
            int identificadorCliente =
                    entrada.read();

            String destinoInterno;

            if (identificadorCliente == 'A') {

                destinoInterno =
                        "app_sensores_iot";

            } else if (identificadorCliente == 'B') {

                destinoInterno =
                        "app_maquininha_pagamento";

            } else {

                System.out.println(
                        "Equipamento não reconhecido."
                );

                return;
            }

            // Lê os dados enviados pelo equipamento.
            byte[] buffer =
                    new byte[2048];

            int bytesLidos =
                    entrada.read(buffer);

            if (bytesLidos <= 0) {
                return;
            }

            byte[] dadosFinais =
                    new byte[bytesLidos];

            System.arraycopy(
                    buffer,
                    0,
                    dadosFinais,
                    0,
                    bytesLidos
            );

            // Identificador único para rastreabilidade.
            String idRastreabilidade =
                    UUID.randomUUID().toString();

            // Converte a comunicação TCP
            // em uma chamada HTTP interna.
            HttpRequest requisicao =
                    HttpRequest.newBuilder()
                            .uri(
                                URI.create(
                                    URL_ALB_INTERNO
                                )
                            )
                            .header(
                                "Destino-Aplicacao",
                                destinoInterno
                            )
                            .header(
                                "Id-Rastreamento",
                                idRastreabilidade
                            )
                            .POST(
                                HttpRequest
                                    .BodyPublishers
                                    .ofByteArray(
                                        dadosFinais
                                    )
                            )
                            .build();

            HttpResponse<byte[]> respostaHttp =
                    clienteHttp.send(
                        requisicao,
                        HttpResponse
                            .BodyHandlers
                            .ofByteArray()
                    );

            // Retorna a resposta para
            // o equipamento de origem.
            saida.write(
                    respostaHttp.body()
            );

            saida.flush();

            System.out.println(
                    "Sucesso! Rastreamento: "
                    + idRastreabilidade
                    + " processado no "
                    + destinoInterno
            );

        } catch (Exception e) {

            System.err.println(
                    "Falha na tradução de protocolo: "
                    + e.getMessage()
            );
        }
    }
}
